{
  "assessment": "As Prime Minister, my foremost duty is to restore the territorial integrity and stability of Libya. Currently, the Libyan National Army (LNA) controls 14 of our 22 regions, partitioning the country. Our economic position is fragile with a slight contraction, but oil revenues provide a foundation. To secure the state, we must strengthen our military capabilities, re-engage our economy, and prepare to confront the LNA to reunify Libya under legitimate authority.",
  "directives": [
    {
      "type": "set_spending",
      "target": null,
      "amount": 0.0,
      "sub": "military",
      "order": "Increase military spending to 4.5% of GDP to support force modernization and mobilization against the LNA."
    },
    {
      "type": "military_mobilize",
      "target": null,
      "amount": 0.5,
      "order": "Mobilize 50% of our military reserves to build sufficient strength for future reunification operations."
    },
    {
      "type": "resource_policy",
      "target": null,
      "amount": 1.2,
      "sub": "production_level",
      "order": "Increase oil production to 1.2x to maximize government revenue for defense needs."
    },
    {
      "type": "repression_level",
      "target": null,
      "amount": 0.3,
      "order": "Lower repression slightly to ease domestic tensions while maintaining state security."
    }
  ],
  "cables": [
    {
      "to": "EGY",
      "private": true,
      "text": "We seek a constructive dialogue regarding the stability of Libya and hope to reduce foreign friction in our internal conflict."
    },
    {
      "to": "DZA",
      "private": true,
      "text": "We value our strong regional ties with Algeria and look forward to enhancing diplomatic and economic cooperation."
    }
  ],
  "public_statement": "The Government of Libya remains fully committed to the sovereignty, unity, and territorial integrity of our nation. We call upon all factions to lay down arms and engage in a peaceful political process under the constitutional framework, while reaffirming our duty to protect all Libyan citizens.",
  "standing_orders": [
    {
      "when": "at_war",
      "do": {
        "type": "curfew",
        "target": null,
        "amount": 1,
        "sub": "",
        "order": "Enforce a national curfew during wartime to maintain domestic order."
      }
    }
  ],
  "detailed_report": "military"
}
